create extension if not exists pgcrypto;
create type public.entry_context as enum ('journey','practice','game','standalone');
create table public.families(id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users on delete cascade, name text, status text not null default 'active', created_at timestamptz not null default now());
create table public.consents(id uuid primary key default gen_random_uuid(), family_id uuid not null references public.families on delete cascade, adult_confirmed boolean not null, terms_version text not null, privacy_version text not null, accepted_at timestamptz not null default now());
create table public.parent_security(family_id uuid primary key references public.families on delete cascade, pin_hash text not null, updated_at timestamptz not null default now());
create table public.players(id uuid primary key default gen_random_uuid(), family_id uuid not null references public.families on delete cascade, first_name text not null check(length(first_name) between 1 and 40), age smallint check(age between 4 and 17), created_at timestamptz not null default now());
create table public.teams(id uuid primary key default gen_random_uuid(), player_id uuid not null references public.players on delete cascade, name text not null, season text, active boolean not null default true);
create table public.games(id uuid primary key default gen_random_uuid(), player_id uuid not null references public.players on delete cascade, team_id uuid references public.teams on delete set null, starts_at timestamptz not null, opponent text, location text, source_uid text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index games_import_uid on public.games(player_id,source_uid) where source_uid is not null;
create table public.chapter_progress(player_id uuid not null references public.players on delete cascade, chapter_id text not null, completed_at timestamptz, primary key(player_id,chapter_id));
create table public.activity_records(id uuid primary key default gen_random_uuid(), player_id uuid not null references public.players on delete cascade, activity_id text not null, context public.entry_context not null, reflection text, created_at timestamptz not null default now());
create table public.challenges(id uuid primary key default gen_random_uuid(), player_id uuid not null references public.players on delete cascade, challenge_id text not null, progress int not null default 0, target int not null check(target>0), completed_at timestamptz, unique(player_id,challenge_id));
create table public.badges(player_id uuid not null references public.players on delete cascade, badge_id text not null, awarded_at timestamptz not null default now(), primary key(player_id,badge_id));
create table public.pre_game(id uuid primary key default gen_random_uuid(), game_id uuid unique not null references public.games on delete cascade, feeling text, confidence smallint check(confidence between 1 and 5), goal_id text, thought_id text, custom_goal text, custom_thought text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.post_game(id uuid primary key default gen_random_uuid(), game_id uuid unique not null references public.games on delete cascade, reflection jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.parent_dugout(id uuid primary key default gen_random_uuid(), game_id uuid references public.games on delete cascade, player_id uuid not null references public.players on delete cascade, themes text[] not null default '{}', note text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.signals(id uuid primary key default gen_random_uuid(), player_id uuid not null references public.players on delete cascade, source_id uuid, theme text not null, strength real not null check(strength between 0 and 1), created_at timestamptz not null default now());
create table public.recommendations(id uuid primary key default gen_random_uuid(), player_id uuid not null references public.players on delete cascade, curriculum_id text not null, rationale text not null, created_at timestamptz not null default now());
create table public.reminders(id uuid primary key default gen_random_uuid(), game_id uuid not null references public.games on delete cascade, kind text not null check(kind in ('pre_game','post_game')), scheduled_for timestamptz not null, sent_at timestamptz, unique(game_id,kind));
alter table public.families enable row level security; alter table public.players enable row level security; alter table public.games enable row level security; alter table public.activity_records enable row level security; alter table public.parent_dugout enable row level security;
create policy family_owner on public.families for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy family_players on public.players for all using(exists(select 1 from public.families f where f.id=family_id and f.owner_id=auth.uid())) with check(exists(select 1 from public.families f where f.id=family_id and f.owner_id=auth.uid()));
create policy family_games on public.games for all using(exists(select 1 from public.players p join public.families f on f.id=p.family_id where p.id=player_id and f.owner_id=auth.uid())) with check(exists(select 1 from public.players p join public.families f on f.id=p.family_id where p.id=player_id and f.owner_id=auth.uid()));
create policy family_activity on public.activity_records for all using(exists(select 1 from public.players p join public.families f on f.id=p.family_id where p.id=player_id and f.owner_id=auth.uid())) with check(exists(select 1 from public.players p join public.families f on f.id=p.family_id where p.id=player_id and f.owner_id=auth.uid()));
create policy family_dugout on public.parent_dugout for all using(exists(select 1 from public.players p join public.families f on f.id=p.family_id where p.id=player_id and f.owner_id=auth.uid())) with check(exists(select 1 from public.players p join public.families f on f.id=p.family_id where p.id=player_id and f.owner_id=auth.uid()));
revoke all on public.parent_security,public.signals from anon,authenticated;
